export function hasAgreementTemplateText(value: unknown): boolean {
  if (!value || typeof value !== "object") return false;
  const record = value as Record<string, unknown>;
  return Object.values(record).some((entry) => {
    if (typeof entry === "string") return entry.trim().length > 0;
    if (!entry || typeof entry !== "object") return false;
    const nested = entry as Record<string, unknown>;
    return (
      (typeof nested.text === "string" && nested.text.trim().length > 0) ||
      (typeof nested.content === "string" && nested.content.trim().length > 0) ||
      (typeof nested.body === "string" && nested.body.trim().length > 0)
    );
  });
}

export function getAgreementTemplatesCandidate(estimate: any): unknown[] {
  if (!estimate || typeof estimate !== "object") return [];
  const record = estimate as Record<string, unknown>;
  const proposalSettings =
    record.proposal_settings && typeof record.proposal_settings === "object"
      ? (record.proposal_settings as Record<string, unknown>)
      : null;

  return [
    record.agreement_templates,
    proposalSettings?.agreement_templates,
    proposalSettings?.agreementTemplates,
  ];
}

export function resolveAgreementTemplates(value: unknown): Record<string, unknown> | null {
  if (!value || typeof value !== "object") return null;
  return hasAgreementTemplateText(value) ? (value as Record<string, unknown>) : null;
}

export function resolveAgreementTemplatesFromEstimate(estimate: any): Record<string, unknown> | null {
  const candidates = getAgreementTemplatesCandidate(estimate);
  for (const candidate of candidates) {
    const resolved = resolveAgreementTemplates(candidate);
    if (resolved) return resolved;
  }
  return null;
}

export function resolveAgreementTemplatesForEstimates(estimates: any[]): {
  templates: Record<string, unknown> | null;
  sourceEstimateId: string | null;
} {
  const requiredKeys = ["job_release_agreement", "job_agreement", "warranty_agreement"] as const;
  const valid = estimates.filter((item) => item && typeof item === "object");
  const merged: Record<string, unknown> = {};
  let sourceEstimateId: string | null = null;
  const genericPhrases = [
    "by approving this estimate",
    "authorize release of work",
    "agreed scope",
  ];
  const extractText = (value: unknown): string => {
    if (typeof value === "string") return value.trim();
    if (value && typeof value === "object") {
      const record = value as Record<string, unknown>;
      if (typeof record.text === "string") return record.text.trim();
      if (typeof record.content === "string") return record.content.trim();
      if (typeof record.body === "string") return record.body.trim();
    }
    return "";
  };
  const scoreText = (text: string): number => {
    if (!text) return -1;
    const normalized = text.toLowerCase();
    const isGeneric = genericPhrases.some((phrase) => normalized.includes(phrase));
    return isGeneric ? Math.min(text.length, 120) : text.length + 1000;
  };

  for (const key of requiredKeys) {
    let bestValue: unknown = null;
    let bestEstimateId: string | null = null;
    let bestScore = -1;
    for (const estimate of valid) {
      const resolved = resolveAgreementTemplatesFromEstimate(estimate);
      if (!resolved) continue;
      const value = resolved[key];
      const text = extractText(value);
      if (!text) continue;
      const score = scoreText(text);
      if (score > bestScore) {
        bestScore = score;
        bestValue = value;
        bestEstimateId = typeof estimate.id === "string" ? estimate.id : null;
      }
    }
    if (bestValue !== null) {
      merged[key] = bestValue;
      if (!sourceEstimateId && bestEstimateId) {
        sourceEstimateId = bestEstimateId;
      }
    }
  }

  if (Object.keys(merged).length > 0) {
    return { templates: merged, sourceEstimateId };
  }

  for (const estimate of valid) {
    const resolved = resolveAgreementTemplatesFromEstimate(estimate);
    if (resolved) {
      return {
        templates: resolved,
        sourceEstimateId: typeof estimate.id === "string" ? estimate.id : null,
      };
    }
  }

  return { templates: null, sourceEstimateId: null };
}

export async function restoreEstimateFromLatestApprovedSnapshot(
  supabase: any,
  estimate: {
    id: string;
    account_id?: string | null;
    proposal_settings?: Record<string, unknown> | null;
  },
): Promise<{ ok: true } | { ok: false; error: string }> {
  const snapshotRaw =
    estimate.proposal_settings &&
    typeof estimate.proposal_settings === "object" &&
    estimate.proposal_settings.latest_approved_snapshot &&
    typeof estimate.proposal_settings.latest_approved_snapshot === "object"
      ? (estimate.proposal_settings.latest_approved_snapshot as Record<string, unknown>)
      : null;

  if (!snapshotRaw) {
    const { error: fallbackDeleteError } = await supabase
      .from("estimate_line_items")
      .delete()
      .eq("estimate_id", estimate.id)
      .eq("is_change_order", true)
      .eq("change_order_approved", false);

    if (fallbackDeleteError) {
      return { ok: false, error: "Failed to decline changes" };
    }

    const { error: fallbackEstimateUpdateError } = await supabase
      .from("estimates")
      .update({
        has_pending_changes: false,
        updated_at: new Date().toISOString(),
      })
      .eq("id", estimate.id);

    if (fallbackEstimateUpdateError) {
      return { ok: false, error: "Failed to finalize declined changes" };
    }

    return { ok: true };
  }

  const snapshotLineItems = Array.isArray(snapshotRaw.line_items) ? snapshotRaw.line_items : [];

  const { error: deleteAllLineItemsError } = await supabase
    .from("estimate_line_items")
    .delete()
    .eq("estimate_id", estimate.id);

  if (deleteAllLineItemsError) {
    return { ok: false, error: "Failed to restore estimate after declining changes" };
  }

  if (snapshotLineItems.length > 0) {
    const restoreLineItems = snapshotLineItems.map((item: any, index: number) => ({
      estimate_id: estimate.id,
      account_id: estimate.account_id ?? null,
      name: item.name || "Line item",
      description: item.description || null,
      quantity: Number(item.quantity) || 0,
      unit: item.unit || "item",
      unit_price: Number(item.unit_price) || 0,
      total: Number(item.total) || 0,
      sort_order: Number(item.sort_order ?? index),
      category: item.category || "other",
      is_change_order: false,
      change_order_type: null,
      change_order_approved: null,
      changed_at: null,
      original_line_item_id: null,
    }));

    const { error: restoreLineItemsError } = await supabase
      .from("estimate_line_items")
      .insert(restoreLineItems);

    if (restoreLineItemsError) {
      return { ok: false, error: "Failed to restore estimate after declining changes" };
    }
  }

  const { error: restoreEstimateError } = await supabase
    .from("estimates")
    .update({
      subtotal: Number(snapshotRaw.subtotal) || 0,
      tax_rate: Number(snapshotRaw.tax_rate) || 0,
      tax: Number(snapshotRaw.tax) || 0,
      discount: Number(snapshotRaw.discount) || 0,
      total: Number(snapshotRaw.total) || 0,
      has_pending_changes: false,
      updated_at: new Date().toISOString(),
    })
    .eq("id", estimate.id);

  if (restoreEstimateError) {
    return { ok: false, error: "Failed to restore estimate after declining changes" };
  }

  return { ok: true };
}

export async function applyEstimateVersionBeforeApproval(
  supabase: any,
  estimateId: string,
  estimateVersionId: string,
): Promise<{ ok: true } | { ok: false; error: string; statusCode: number }> {
  const { data: version, error: versionError } = await supabase
    .from("estimate_versions")
    .select("id, estimate_id, account_id, subtotal, tax_rate, tax, discount, total, profit_margin, surcharge, notes, line_items")
    .eq("id", estimateVersionId)
    .eq("estimate_id", estimateId)
    .maybeSingle();

  if (versionError || !version) {
    return { ok: false, error: "Selected estimate version was not found", statusCode: 400 };
  }

  const { error: deleteLineItemsError } = await supabase
    .from("estimate_line_items")
    .delete()
    .eq("estimate_id", estimateId);

  if (deleteLineItemsError) {
    return { ok: false, error: "Failed to apply selected estimate version", statusCode: 500 };
  }

  const lineItems = Array.isArray(version.line_items) ? version.line_items : [];
  if (lineItems.length > 0) {
    const inserts = lineItems.map((item: any, index: number) => ({
      estimate_id: estimateId,
      account_id: version.account_id,
      name: item.name || "Line item",
      description: item.description || null,
      quantity: Number(item.quantity) || 0,
      unit: item.unit || "item",
      unit_price: Number(item.unit_price) || 0,
      total: Number(item.total) || 0,
      sort_order: Number(item.sort_order ?? index),
      category: item.category || "other",
      is_change_order: false,
      change_order_type: null,
      change_order_approved: null,
      changed_at: null,
      original_line_item_id: null,
    }));

    const { error: insertLineItemsError } = await supabase
      .from("estimate_line_items")
      .insert(inserts);

    if (insertLineItemsError) {
      return { ok: false, error: "Failed to apply selected estimate version", statusCode: 500 };
    }
  }

  const { error: updateEstimateError } = await supabase
    .from("estimates")
    .update({
      subtotal: Number(version.subtotal) || 0,
      tax_rate: Number(version.tax_rate) || 0,
      tax: Number(version.tax) || 0,
      discount: Number(version.discount) || 0,
      total: Number(version.total) || 0,
      profit_margin: Number(version.profit_margin) || 0,
      surcharge: Number(version.surcharge) || 0,
      notes: version.notes || null,
      updated_at: new Date().toISOString(),
    })
    .eq("id", estimateId);

  if (updateEstimateError) {
    return { ok: false, error: "Failed to apply selected estimate version", statusCode: 500 };
  }

  return { ok: true };
}

export async function pruneEstimateVersionsAfterApproval(
  supabase: any,
  estimateId: string,
  keepVersionId: string | null,
): Promise<{ ok: true } | { ok: false; error: string }> {
  let deleteQuery = supabase
    .from("estimate_versions")
    .delete()
    .eq("estimate_id", estimateId);

  if (keepVersionId) {
    deleteQuery = deleteQuery.neq("id", keepVersionId);
  }

  const { error } = await deleteQuery;
  if (error) {
    return { ok: false, error: "Failed to remove unused estimate versions" };
  }

  return { ok: true };
}

import {
  applyEstimateVersionBeforeApproval,
  pruneEstimateVersionsAfterApproval,
  restoreEstimateFromLatestApprovedSnapshot,
} from "./estimate-snapshot.ts";
import {
  isManualApprovalPhotoUrlColumnMissing,
  uploadSignatureDataUrl,
} from "./signature.ts";

export async function handleEstimateAction(
  supabase: any,
  estimate: {
    id: string;
    status: string;
    expires_at: string | null;
    job_id: string | null;
    recurring_job_id?: string | null;
    updated_at: string;
    has_pending_changes?: boolean;
    account_id?: string | null;
    proposal_settings?: Record<string, unknown> | null;
  },
  action: "approve" | "decline" | "approve_changes" | "decline_changes",
  portalJobId: string | null,
  jsonResponse: (body: unknown, status?: number) => Response,
  clientUpdatedAt?: string,
  estimateVersionId?: string | null,
  signatureDataUrl?: string | null,
  agreementAcceptance?: Record<string, boolean> | null,
  agreementTemplates?: Record<string, unknown> | null,
  requiredDocumentConfigIds?: string[],
) {
  void portalJobId;
  const isWarrantyEnabledForVersion = (versionId: string | null | undefined) => {
    if (!versionId) return true;
    const settingsRaw = estimate?.proposal_settings?.version_warranty_enabled;
    const settings =
      settingsRaw && typeof settingsRaw === "object" && !Array.isArray(settingsRaw)
        ? (settingsRaw as Record<string, unknown>)
        : {};
    const value = settings[versionId];
    return value === undefined ? true : value === true;
  };

  if (clientUpdatedAt && estimate.updated_at !== clientUpdatedAt) {
    return jsonResponse({
      error: "This estimate has been updated since you loaded this page. Please refresh the page to see the latest version before approving."
    }, 409);
  }

  if (action === "approve_changes" || action === "decline_changes") {
    if (!estimate.has_pending_changes) {
      return jsonResponse({ error: "No pending changes to approve" }, 400);
    }

    if (action === "approve_changes") {
      let uploadedSignature: { filePath: string; publicUrl: string } | null = null;
      if (signatureDataUrl) {
        const uploadedResult = await uploadSignatureDataUrl(supabase, estimate.id, signatureDataUrl);
        if (!uploadedResult.ok) {
          return jsonResponse({ error: uploadedResult.error }, uploadedResult.statusCode);
        }
        uploadedSignature = { filePath: uploadedResult.filePath, publicUrl: uploadedResult.publicUrl };
      }

      const { error: approveError } = await supabase
        .from("estimate_line_items")
        .update({ change_order_approved: true })
        .eq("estimate_id", estimate.id)
        .eq("is_change_order", true)
        .eq("change_order_approved", false);

      if (approveError) {
        if (uploadedSignature?.filePath) {
          await supabase.storage.from("lead-photos").remove([uploadedSignature.filePath]);
        }
        return jsonResponse({ error: "Failed to approve changes" }, 500);
      }

      const changeApprovalUpdatePayload: Record<string, unknown> = {
        approved_via: "customer_link",
        accepted_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      };

      if (uploadedSignature) {
        changeApprovalUpdatePayload.manual_approval_photo_url = uploadedSignature.publicUrl;
      }

      const { error: changeApprovalUpdateError } = await supabase
        .from("estimates")
        .update(changeApprovalUpdatePayload)
        .eq("id", estimate.id);

      if (changeApprovalUpdateError && uploadedSignature && isManualApprovalPhotoUrlColumnMissing(changeApprovalUpdateError)) {
        const { manual_approval_photo_url: _manualApprovalPhotoUrl, ...fallbackPayload } = changeApprovalUpdatePayload;
        const { error: fallbackError } = await supabase
          .from("estimates")
          .update(fallbackPayload)
          .eq("id", estimate.id);

        if (uploadedSignature.filePath) {
          await supabase.storage.from("lead-photos").remove([uploadedSignature.filePath]);
        }

        if (fallbackError) {
          return jsonResponse({ error: "Failed to finalize change-order approval" }, 500);
        }
      } else if (changeApprovalUpdateError) {
        if (uploadedSignature?.filePath) {
          await supabase.storage.from("lead-photos").remove([uploadedSignature.filePath]);
        }
        return jsonResponse({ error: "Failed to finalize change-order approval" }, 500);
      }

      return jsonResponse({ success: true, message: "Changes approved" });
    }

    const restoreResult = await restoreEstimateFromLatestApprovedSnapshot(supabase, estimate);
    if (!restoreResult.ok) {
      return jsonResponse({ error: restoreResult.error }, 500);
    }

    return jsonResponse({ success: true, message: "Changes declined" });
  }

  if (estimate.status === "accepted") {
    return jsonResponse({ error: "This estimate has already been approved" }, 400);
  }

  if (estimate.status === "declined") {
    return jsonResponse({ error: "This estimate has already been declined" }, 400);
  }

  if (estimate.expires_at && new Date(estimate.expires_at) < new Date()) {
    return jsonResponse({ error: "This estimate has expired" }, 400);
  }

  if (action === "approve") {
    const activeVersionId =
      estimateVersionId ||
      (typeof estimate?.proposal_settings?.recommended_version_id === "string"
        ? estimate.proposal_settings.recommended_version_id
        : null);
    const requiredAgreementKeys = ["job_agreement"];
    if (isWarrantyEnabledForVersion(activeVersionId)) {
      requiredAgreementKeys.push("warranty_agreement");
    }
    const acceptedKeys = requiredAgreementKeys.filter((key) => agreementAcceptance?.[key] === true);
    if (acceptedKeys.length !== requiredAgreementKeys.length) {
      return jsonResponse({ error: "All required agreements must be accepted before approval." }, 400);
    }
    const requiredConfigIds = (requiredDocumentConfigIds || []).filter((id) => typeof id === "string" && id.length > 0);
    const allRequiredConfigsAccepted = requiredConfigIds.every((id) => agreementAcceptance?.[id] === true);
    if (!allRequiredConfigsAccepted) {
      return jsonResponse({ error: "Please accept all required documents before approval." }, 400);
    }

    let uploadedSignature: { filePath: string; publicUrl: string } | null = null;
    if (signatureDataUrl) {
      const uploadedResult = await uploadSignatureDataUrl(supabase, estimate.id, signatureDataUrl);
      if (!uploadedResult.ok) {
        return jsonResponse({ error: uploadedResult.error }, uploadedResult.statusCode);
      }
      uploadedSignature = { filePath: uploadedResult.filePath, publicUrl: uploadedResult.publicUrl };
    }

    if (estimateVersionId) {
      const applyResult = await applyEstimateVersionBeforeApproval(supabase, estimate.id, estimateVersionId);
      if (!applyResult.ok) {
        if (uploadedSignature?.filePath) {
          await supabase.storage.from("lead-photos").remove([uploadedSignature.filePath]);
        }
        return jsonResponse({ error: applyResult.error }, applyResult.statusCode);
      }
    }

    const estimateUpdatePayload: Record<string, unknown> = {
      status: "accepted",
      accepted_at: new Date().toISOString(),
      approved_via: "customer_link",
      agreement_acceptance: {
        job_agreement: agreementAcceptance?.job_agreement === true,
        warranty_agreement: agreementAcceptance?.warranty_agreement === true,
        accepted_at: new Date().toISOString(),
      },
      updated_at: new Date().toISOString(),
    };
    if (agreementTemplates && typeof agreementTemplates === "object") {
      const templates = agreementTemplates as Record<string, unknown>;
      estimateUpdatePayload.agreement_templates = {
        job_agreement: templates.job_agreement,
        warranty_agreement: templates.warranty_agreement,
      };
    }

    if (uploadedSignature) {
      estimateUpdatePayload.manual_approval_photo_url = uploadedSignature.publicUrl;
    }

    const { error } = await supabase
      .from("estimates")
      .update(estimateUpdatePayload)
      .eq("id", estimate.id);

    if (error && uploadedSignature && isManualApprovalPhotoUrlColumnMissing(error)) {
      const { manual_approval_photo_url: _manualApprovalPhotoUrl, ...fallbackPayload } = estimateUpdatePayload;
      const { error: fallbackError } = await supabase
        .from("estimates")
        .update(fallbackPayload)
        .eq("id", estimate.id);

      if (uploadedSignature.filePath) {
        await supabase.storage.from("lead-photos").remove([uploadedSignature.filePath]);
      }

      if (fallbackError) {
        return jsonResponse({ error: "Failed to approve estimate" }, 500);
      }
    } else if (error) {
      if (uploadedSignature?.filePath) {
        await supabase.storage.from("lead-photos").remove([uploadedSignature.filePath]);
      }
      return jsonResponse({ error: "Failed to approve estimate" }, 500);
    }

    const pruneResult = await pruneEstimateVersionsAfterApproval(
      supabase,
      estimate.id,
      estimateVersionId ?? null,
    );
    if (!pruneResult.ok) {
      console.error("Failed to prune estimate versions after approval:", pruneResult.error);
    }

    return jsonResponse({ success: true, message: "Estimate approved" });
  }

  const { error: declineError } = await supabase
    .from("estimates")
    .update({
      status: "declined",
      updated_at: new Date().toISOString(),
    })
    .eq("id", estimate.id);

  if (declineError) {
    return jsonResponse({ error: "Failed to decline estimate" }, 500);
  }

  if (estimate.job_id) {
    await supabase
      .from("leads")
      .update({
        approval_status: "rejected",
        approval_reason: "estimate_declined",
        rejected_at: new Date().toISOString(),
      })
      .eq("id", estimate.job_id);

    const { data: estimateJobLead } = await supabase
      .from("leads")
      .select("estimate_job_id")
      .eq("id", estimate.job_id)
      .maybeSingle();

    if (estimateJobLead?.estimate_job_id) {
      await supabase
        .from("leads")
        .update({ status: "completed" })
        .eq("id", estimateJobLead.estimate_job_id);
    }
  }

  return jsonResponse({ success: true, message: "Estimate declined" });
}

import { resolveAgreementTemplatesForEstimates } from "./agreement-templates.ts";
import { handleEstimateAction } from "./handle-estimate-action.ts";
import { fetchPortalDocumentsForLeadFamily } from "./portal-documents.ts";

export async function handleRecurringJobPortal(
  supabase: any,
  supabaseUrl: string,
  recurringJob: any,
  req: Request,
  jsonResponse: (body: unknown, status?: number) => Response,
) {
  if (req.method === "POST") {
    const body = await req.json();
    const action = body.action;
    const clientUpdatedAt = body.updated_at;
    const estimateVersionId = typeof body.estimate_version_id === "string" ? body.estimate_version_id : null;
    const signatureDataUrl =
      typeof body.signature_data_url === "string"
        ? body.signature_data_url
        : typeof body.signatureDataUrl === "string"
          ? body.signatureDataUrl
          : null;
    const agreementAcceptance =
      body && typeof body.agreement_acceptance === "object" && body.agreement_acceptance
        ? body.agreement_acceptance
        : null;
    const agreementTemplates =
      body && typeof body.agreement_templates === "object" && body.agreement_templates
        ? body.agreement_templates
        : null;
    let requiredDocumentConfigIds: string[] = [];

    if (action !== "approve" && action !== "decline" && action !== "approve_changes" && action !== "decline_changes") {
      return jsonResponse({ error: "Invalid action" }, 400);
    }

    const { data: estimate, error: estError } = await supabase
      .from("estimates")
      .select("id, status, expires_at, job_id, recurring_job_id, updated_at, has_pending_changes, account_id, proposal_settings")
      .eq("recurring_job_id", recurringJob.id)
      .maybeSingle();

    if (estError || !estimate) {
      return jsonResponse({ error: "No quote found for this job schedule" }, 404);
    }
    if (action === "approve") {
      const baseDocumentLeadIds = [
        typeof estimate?.job_id === "string" ? estimate.job_id : null,
        ...((await supabase
          .from("leads")
          .select("id")
          .eq("recurring_job_id", recurringJob.id)).data || []).map((row: any) => String(row.id || "")),
      ].filter((value): value is string => Boolean(value));
      const portalDocuments = await fetchPortalDocumentsForLeadFamily(
        supabase,
        supabaseUrl,
        baseDocumentLeadIds,
        "recurring approval required documents",
      );
      requiredDocumentConfigIds = (portalDocuments.configs || [])
        .filter((config: any) => {
          const timing = String(config?.email_timing || "").trim().toLowerCase().replace(/[\s-]+/g, "_");
          return config?.include_in_job === true
            && timing === "on_estimate_approval"
            && config?.requires_signature === true;
        })
        .map((config: any) => String(config.id || ""))
        .filter(Boolean);
    }

    return await handleEstimateAction(
      supabase,
      estimate,
      action,
      null,
      jsonResponse,
      clientUpdatedAt,
      estimateVersionId,
      signatureDataUrl,
      agreementAcceptance,
      agreementTemplates,
      requiredDocumentConfigIds,
    );
  }

  if (req.method !== "GET") {
    return jsonResponse({ error: "Method not allowed" }, 405);
  }

  const { data: instances } = await supabase
    .from("leads")
    .select("id, name, status, recurring_instance_number")
    .eq("recurring_job_id", recurringJob.id)
    .order("recurring_instance_number", { ascending: true });

  const instanceIds = (instances || []).map((i: any) => i.id);

  const [
    { data: account },
    { data: estimate },
    { data: allSchedules },
    { data: allBeforePhotos },
    { data: allAfterPhotos },
    { data: allInteractions },
  ] = await Promise.all([
    supabase
      .from("accounts")
      .select("company_name, company_email, company_phone, logo_url, settings")
      .eq("id", recurringJob.account_id)
      .maybeSingle(),

    supabase
      .from("estimates")
      .select(`
        id, job_id, subtotal, tax_rate, tax, discount, total, profit_margin, surcharge, notes, status, created_at, updated_at, accepted_at, approved_via, manual_approval_photo_url,
        original_subtotal, original_tax, original_discount, original_total, original_notes, has_pending_changes,
        proposal_settings, project_visualization_image_url, agreement_templates, agreement_acceptance,
        line_items:estimate_line_items(
          id, name, description, quantity, unit, unit_price, total,
          sort_order, is_change_order, change_order_type, change_order_approved, changed_at
        )
      `)
      .eq("recurring_job_id", recurringJob.id)
      .maybeSingle(),

    instanceIds.length > 0
      ? supabase
          .from("job_schedules")
          .select("id, lead_id, scheduled_date, scheduled_time_start, scheduled_time_end, is_completed")
          .in("lead_id", instanceIds)
          .order("scheduled_date", { ascending: true })
      : { data: [] },

    instanceIds.length > 0
      ? supabase
          .from("lead_photos")
          .select("id, lead_id, file_path, created_at")
          .in("lead_id", instanceIds)
          .eq("photo_type", "before")
          .order("created_at", { ascending: true })
      : { data: [] },

    instanceIds.length > 0
      ? supabase
          .from("lead_photos")
          .select("id, lead_id, file_path, created_at")
          .in("lead_id", instanceIds)
          .eq("photo_type", "after")
          .order("created_at", { ascending: true })
      : { data: [] },

    instanceIds.length > 0
      ? supabase
          .from("interactions")
          .select("id, type, summary, created_at, lead_id")
          .in("lead_id", instanceIds)
          .in("type", ["note", "status_change", "call", "email", "sms"])
          .order("created_at", { ascending: false })
          .limit(30)
      : { data: [] },
  ]);

  const buildPhotoUrls = (photos: any[] | null) =>
    (photos || []).map((p: any) => ({
      id: p.id,
      url: `${supabaseUrl}/storage/v1/object/public/lead-photos/${p.file_path}`,
      created_at: p.created_at,
    }));

  const filteredLineItems = estimate
    ? (estimate.line_items || [])
        .filter((li: any) => !li.is_change_order || li.change_order_type !== "deleted")
        .sort((a: any, b: any) => (a.sort_order || 0) - (b.sort_order || 0))
    : [];

  let originalLineItemsRecurring = null;
  if (estimate?.original_total) {
    const { data: originals } = await supabase
      .from("estimate_line_items_original")
      .select("id, original_line_item_id, name, description, quantity, unit, unit_price, total, sort_order")
      .eq("estimate_id", estimate.id)
      .order("sort_order");
    originalLineItemsRecurring = originals;
  }

  const { data: estimateVersionsRecurring } = estimate
    ? await supabase
        .from("estimate_versions")
        .select("id, name, subtotal, tax_rate, tax, discount, total, profit_margin, notes, line_items, created_at, updated_at")
        .eq("estimate_id", estimate.id)
        .order("created_at", { ascending: true })
    : { data: [] };

  const recurringScopeJobIds = [
    typeof estimate?.job_id === "string" ? estimate.job_id : null,
  ].filter((value): value is string => Boolean(value));

  let recurringScopeItems: string[] = [];
  if (recurringScopeJobIds.length > 0) {
    const { data: recurringChecklistRows } = await supabase
      .from("job_checklist_items")
      .select("job_id, label, sort_order")
      .in("job_id", recurringScopeJobIds)
      .order("sort_order", { ascending: true });

    const grouped = new Map<string, string[]>();
    for (const row of recurringChecklistRows || []) {
      const label = String((row as any).label || "").trim();
      const rowJobId = String((row as any).job_id || "");
      if (!label || !rowJobId) continue;
      const current = grouped.get(rowJobId) || [];
      current.push(label);
      grouped.set(rowJobId, current);
    }

    for (const candidateJobId of recurringScopeJobIds) {
      const items = grouped.get(candidateJobId) || [];
      if (items.length > 0) {
        recurringScopeItems = items;
        break;
      }
    }
  }

  const instanceMap = new Map((instances || []).map((i: any) => [i.id, i]));
  const schedulesWithVisit = (allSchedules || []).map((s: any) => {
    const inst = instanceMap.get(s.lead_id);
    return {
      scheduled_date: s.scheduled_date,
      scheduled_time_start: s.scheduled_time_start,
      scheduled_time_end: s.scheduled_time_end,
      is_completed: s.is_completed,
      visit_number: inst?.recurring_instance_number || null,
      visit_status: inst?.status || null,
    };
  });

  const recurringResolvedAgreement = resolveAgreementTemplatesForEstimates([estimate]);
  const portalDocuments = await fetchPortalDocumentsForLeadFamily(
    supabase,
    supabaseUrl,
    [...recurringScopeJobIds, ...instanceIds],
    "recurring portal job documents",
  );

  return jsonResponse({
    job: {
      name: recurringJob.name,
      address: recurringJob.address,
      service_type: recurringJob.service_type,
      status: "recurring",
      description: recurringJob.description,
      created_at: null,
      customer: recurringJob.customer,
      is_recurring: true,
      frequency: recurringJob.frequency,
    },
    company: account
      ? {
          company_name: account.company_name,
          company_email: account.company_email,
          company_phone: account.company_phone,
          logo_url: account.logo_url,
          portal_color: account.settings?.client_portal_color ?? null,
          portal_text_color: account.settings?.client_portal_text_color ?? null,
          client_portal_color: account.settings?.client_portal_color ?? null,
          client_portal_text_color: account.settings?.client_portal_text_color ?? null,
          settings: account.settings ?? null,
        }
      : {},
    schedules: schedulesWithVisit,
    estimate: estimate
      ? {
          id: estimate.id,
          job_id: estimate.job_id ?? null,
          total: estimate.total,
          subtotal: estimate.subtotal,
          profit_margin: estimate.profit_margin,
          tax_rate: estimate.tax_rate,
          tax: estimate.tax,
          discount: estimate.discount,
          notes: estimate.notes,
          status: estimate.status,
          updated_at: estimate.updated_at,
          accepted_at: estimate.accepted_at ?? null,
          approved_via: estimate.approved_via ?? null,
          manual_approval_photo_url: estimate.manual_approval_photo_url ?? null,
          line_items: filteredLineItems,
          original_total: estimate.original_total,
          original_subtotal: estimate.original_subtotal,
          original_tax: estimate.original_tax,
          original_discount: estimate.original_discount,
          original_notes: estimate.original_notes,
          original_line_items: originalLineItemsRecurring,
          has_pending_changes: estimate.has_pending_changes,
          proposal_settings: estimate.proposal_settings || null,
          scope_of_work_items: recurringScopeItems,
          project_visualization_image_url: estimate.project_visualization_image_url || null,
          agreement_templates: recurringResolvedAgreement.templates,
          agreement_source_estimate_id: recurringResolvedAgreement.sourceEstimateId,
          agreement_acceptance: estimate.agreement_acceptance || null,
          estimate_versions: estimateVersionsRecurring || [],
          job_document_config_lead_id: portalDocuments.leadId,
          job_document_configs: portalDocuments.configs,
          job_documents: portalDocuments.documents,
        }
      : null,
    photos: {
      before: buildPhotoUrls(allBeforePhotos),
      after: buildPhotoUrls(allAfterPhotos),
    },
    invoice: null,
    estimate_visit_schedules: [],
    activity: (allInteractions || []).map((i: any) => ({
      type: i.type,
      summary: i.summary,
      created_at: i.created_at,
    })),
  });
}

import { resolveAgreementTemplatesForEstimates } from "./agreement-templates.ts";
import { fetchPortalDocumentsForLeadFamily } from "./portal-documents.ts";
import { getJobReleaseForLead, isLeadFullyPaid } from "./job-release.ts";

export async function handleSingleJobGet(
  supabase: any,
  supabaseUrl: string,
  job: any,
  jsonResponse: (body: unknown, status?: number) => Response,
) {
  const [
    { data: account },
    { data: schedules },
    { data: estimate },
    { data: beforePhotos },
    { data: afterPhotos },
    { data: interactions },
  ] = await Promise.all([
    supabase
      .from("accounts")
      .select("company_name, company_email, company_phone, logo_url, settings")
      .eq("id", job.account_id)
      .maybeSingle(),

    supabase
      .from("job_schedules")
      .select("id, scheduled_date, scheduled_time_start, scheduled_time_end, is_completed")
      .eq("lead_id", job.id)
      .order("scheduled_date", { ascending: true }),

    supabase
      .from("estimates")
      .select(
        `
        id, job_id, subtotal, tax_rate, tax, discount, total, profit_margin, surcharge, notes, status, created_at, updated_at, accepted_at, approved_via, manual_approval_photo_url,
        original_subtotal, original_tax, original_discount, original_total, original_notes, has_pending_changes,
        proposal_settings, project_visualization_image_url, agreement_templates, agreement_acceptance,
        line_items:estimate_line_items(
          id, name, description, quantity, unit, unit_price, total,
          sort_order, is_change_order, change_order_type, change_order_approved, changed_at
        )
      `
      )
      .eq("job_id", job.id)
      .maybeSingle(),

    supabase
      .from("lead_photos")
      .select("id, file_path, created_at")
      .eq("lead_id", job.id)
      .eq("photo_type", "before")
      .order("created_at", { ascending: true }),

    supabase
      .from("lead_photos")
      .select("id, file_path, created_at")
      .eq("lead_id", job.id)
      .eq("photo_type", "after")
      .order("created_at", { ascending: true }),

    supabase
      .from("interactions")
      .select("id, type, summary, created_at")
      .eq("lead_id", job.id)
      .in("type", ["note", "status_change", "call", "email", "sms"])
      .order("created_at", { ascending: false })
      .limit(10),
  ]);

  let parentEstimate = estimate;
  if (!parentEstimate && job.estimate_job_id) {
    const { data: parentLead } = await supabase
      .from("leads")
      .select("id")
      .eq("id", job.estimate_job_id)
      .maybeSingle();

    if (parentLead) {
      const { data: pe } = await supabase
        .from("estimates")
        .select(
          `
          id, job_id, subtotal, tax_rate, tax, discount, total, profit_margin, surcharge, notes, status, created_at, updated_at, accepted_at, approved_via, manual_approval_photo_url,
          original_subtotal, original_tax, original_discount, original_total, original_notes, has_pending_changes,
          proposal_settings, project_visualization_image_url, agreement_templates, agreement_acceptance,
          line_items:estimate_line_items(
            id, name, description, quantity, unit, unit_price, total,
            sort_order, is_change_order, change_order_type, change_order_approved
          )
        `
        )
        .eq("job_id", parentLead.id)
        .maybeSingle();
      parentEstimate = pe;
    }
  }

  const { data: invoice } = await supabase
    .from("invoices")
    .select("id, stripe_invoice_url, status")
    .eq("lead_id", job.id)
    .order("created_at", { ascending: false })
    .limit(1)
    .maybeSingle();
  const fullyPaid = await isLeadFullyPaid(supabase, job.id);
  const jobRelease = await getJobReleaseForLead(supabase, job.id);

  let estimateVisitSchedules: any[] = [];
  if (job.estimate_job_id) {
    const { data: evSchedules } = await supabase
      .from("job_schedules")
      .select("scheduled_date, scheduled_time_start, scheduled_time_end, is_completed")
      .eq("lead_id", job.estimate_job_id)
      .order("scheduled_date", { ascending: true });
    estimateVisitSchedules = evSchedules || [];
  }

  const buildPhotoUrls = (photos: any[] | null) =>
    (photos || []).map((p: any) => ({
      id: p.id,
      url: `${supabaseUrl}/storage/v1/object/public/lead-photos/${p.file_path}`,
      created_at: p.created_at,
    }));

  const filteredLineItems = parentEstimate
    ? (parentEstimate.line_items || [])
        .filter(
          (li: any) =>
            !li.is_change_order || li.change_order_type !== "deleted"
        )
        .sort(
          (a: any, b: any) => (a.sort_order || 0) - (b.sort_order || 0)
        )
    : [];

  let originalLineItems = null;
  if (parentEstimate?.original_total) {
    const { data: originals } = await supabase
      .from("estimate_line_items_original")
      .select("id, original_line_item_id, name, description, quantity, unit, unit_price, total, sort_order")
      .eq("estimate_id", parentEstimate.id)
      .order("sort_order");
    originalLineItems = originals;
  }

  const { data: estimateVersions } = parentEstimate
    ? await supabase
        .from("estimate_versions")
        .select("id, name, subtotal, tax_rate, tax, discount, total, profit_margin, notes, line_items, created_at, updated_at")
        .eq("estimate_id", parentEstimate.id)
        .order("created_at", { ascending: true })
    : { data: [] };

  const relatedEstimateJobIds = new Set<string>();
  if (job?.id) relatedEstimateJobIds.add(job.id);
  if (job?.estimate_job_id) relatedEstimateJobIds.add(job.estimate_job_id);
  if (estimate?.job_id) relatedEstimateJobIds.add(estimate.job_id);
  if (parentEstimate?.job_id) relatedEstimateJobIds.add(parentEstimate.job_id);

  let fallbackEstimates: any[] = [];
  if (relatedEstimateJobIds.size > 0) {
    const { data: relatedEstimates } = await supabase
      .from("estimates")
      .select("id, job_id, agreement_templates, updated_at")
      .in("job_id", Array.from(relatedEstimateJobIds))
      .order("updated_at", { ascending: false });
    fallbackEstimates = relatedEstimates || [];
  }

  const resolvedAgreement = resolveAgreementTemplatesForEstimates([
    parentEstimate,
    estimate,
    ...fallbackEstimates,
  ]);

  const scopeJobIds = [
    typeof job?.id === "string" ? job.id : null,
    typeof job?.estimate_job_id === "string" ? job.estimate_job_id : null,
    typeof estimate?.job_id === "string" ? estimate.job_id : null,
    typeof parentEstimate?.job_id === "string" ? parentEstimate.job_id : null,
  ].filter((value): value is string => Boolean(value));

  let scopeItems: string[] = [];
  if (scopeJobIds.length > 0) {
    const { data: checklistRows } = await supabase
      .from("job_checklist_items")
      .select("job_id, label, sort_order")
      .in("job_id", scopeJobIds)
      .order("sort_order", { ascending: true });

    const grouped = new Map<string, string[]>();
    for (const row of checklistRows || []) {
      const label = String((row as any).label || "").trim();
      const rowJobId = String((row as any).job_id || "");
      if (!label || !rowJobId) continue;
      const current = grouped.get(rowJobId) || [];
      current.push(label);
      grouped.set(rowJobId, current);
    }

    for (const candidateJobId of scopeJobIds) {
      const items = grouped.get(candidateJobId) || [];
      if (items.length > 0) {
        scopeItems = items;
        break;
      }
    }
  }

  const baseDocumentLeadIds = [
    typeof parentEstimate?.job_id === "string" ? parentEstimate.job_id : null,
    typeof estimate?.job_id === "string" ? estimate.job_id : null,
    typeof job?.estimate_job_id === "string" ? job.estimate_job_id : null,
    typeof job?.id === "string" ? job.id : null,
  ].filter((value): value is string => Boolean(value));
  const portalDocuments = await fetchPortalDocumentsForLeadFamily(
    supabase,
    supabaseUrl,
    baseDocumentLeadIds,
    "portal job documents",
  );

  return jsonResponse({
    job: {
      name: job.name,
      address: job.address,
      service_type: job.service_type,
      status: job.status,
      description: job.description,
      created_at: job.created_at,
      customer: job.customer,
    },
    company: account
      ? {
          company_name: account.company_name,
          company_email: account.company_email,
          company_phone: account.company_phone,
          logo_url: account.logo_url,
          portal_color: account.settings?.client_portal_color ?? null,
          portal_text_color: account.settings?.client_portal_text_color ?? null,
          client_portal_color: account.settings?.client_portal_color ?? null,
          client_portal_text_color: account.settings?.client_portal_text_color ?? null,
          settings: account.settings ?? null,
        }
      : {},
    schedules: (schedules || []).map((s: any) => ({
      scheduled_date: s.scheduled_date,
      scheduled_time_start: s.scheduled_time_start,
      scheduled_time_end: s.scheduled_time_end,
      is_completed: s.is_completed,
    })),
    estimate: parentEstimate
      ? {
          id: parentEstimate.id,
          job_id: parentEstimate.job_id ?? null,
          total: parentEstimate.total,
          subtotal: parentEstimate.subtotal,
          profit_margin: parentEstimate.profit_margin,
          tax_rate: parentEstimate.tax_rate,
          tax: parentEstimate.tax,
          discount: parentEstimate.discount,
          notes: parentEstimate.notes,
          status: parentEstimate.status,
          updated_at: parentEstimate.updated_at,
          accepted_at: parentEstimate.accepted_at ?? null,
          approved_via: parentEstimate.approved_via ?? null,
          manual_approval_photo_url: parentEstimate.manual_approval_photo_url ?? null,
          line_items: filteredLineItems,
          original_total: parentEstimate.original_total,
          original_subtotal: parentEstimate.original_subtotal,
          original_tax: parentEstimate.original_tax,
          original_discount: parentEstimate.original_discount,
          original_notes: parentEstimate.original_notes,
          original_line_items: originalLineItems,
          has_pending_changes: parentEstimate.has_pending_changes,
          proposal_settings: parentEstimate.proposal_settings || null,
          scope_of_work_items: scopeItems,
          project_visualization_image_url: parentEstimate.project_visualization_image_url || null,
          agreement_templates: resolvedAgreement.templates,
          agreement_source_estimate_id: resolvedAgreement.sourceEstimateId,
          agreement_acceptance: parentEstimate.agreement_acceptance || null,
          estimate_versions: estimateVersions || [],
          job_document_config_lead_id: portalDocuments.leadId,
          job_document_configs: portalDocuments.configs,
          job_documents: portalDocuments.documents,
        }
      : null,
    photos: {
      before: buildPhotoUrls(beforePhotos),
      after: buildPhotoUrls(afterPhotos),
    },
    invoice: invoice ? {
      stripe_invoice_url: invoice.stripe_invoice_url,
      status: invoice.status,
    } : null,
    job_release: jobRelease
      ? {
          id: jobRelease.id,
          status: jobRelease.status,
          release_text: jobRelease.release_text,
          signed_at: jobRelease.signed_at,
          signature_image_url: jobRelease.signature_image_url,
          requested_at: jobRelease.requested_at,
        }
      : null,
    is_fully_paid: fullyPaid,
    estimate_visit_schedules: estimateVisitSchedules.map((s: any) => ({
      scheduled_date: s.scheduled_date,
      scheduled_time_start: s.scheduled_time_start,
      scheduled_time_end: s.scheduled_time_end,
      is_completed: s.is_completed,
    })),
    activity: (interactions || []).map((i: any) => ({
      type: i.type,
      summary: i.summary,
      created_at: i.created_at,
    })),
  });
}

import { createClient } from "npm:@supabase/supabase-js@2";
import { handleEstimateAction } from "./handle-estimate-action.ts";
import { handleRecurringJobPortal } from "./handle-recurring-job-portal.ts";
import { handleSingleJobGet } from "./handle-single-job-get.ts";
import { fetchPortalDocumentsForLeadFamily } from "./portal-documents.ts";
import { signJobRelease } from "./job-release.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, PUT, DELETE, OPTIONS",
  "Access-Control-Allow-Headers":
    "Content-Type, Authorization, X-Client-Info, Apikey",
};

function jsonResponse(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      ...corsHeaders,
      "Content-Type": "application/json",
      "Cache-Control": "no-store, no-cache, must-revalidate, proxy-revalidate, max-age=0",
      Pragma: "no-cache",
      Expires: "0",
    },
  });
}

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { status: 200, headers: corsHeaders });
  }

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    const url = new URL(req.url);
    const token = url.searchParams.get("token");
    const jobId = url.searchParams.get("jobId");

    if (!token) {
      return jsonResponse({ error: "Missing share token" }, 400);
    }

    const { data: customer } = await supabase
      .from("customers")
      .select("id, name, email, phone, account_id")
      .eq("client_portal_token", token)
      .maybeSingle();

    if (customer) {
      return await handleClientPortal(supabase, supabaseUrl, customer, jobId, req);
    }

    const { data: recurringJob } = await supabase
      .from("recurring_jobs")
      .select("id, name, address, service_type, description, account_id, customer_id, frequency, start_date, end_date, client_share_token, customer:customers!customer_id(name, email, phone)")
      .eq("client_share_token", token)
      .maybeSingle();

    if (recurringJob) {
      return await handleRecurringJobPortal(supabase, supabaseUrl, recurringJob, req, jsonResponse);
    }

    const { data: job, error: jobError } = await supabase
      .from("leads")
      .select(
        `
        id,
        name,
        address,
        service_type,
        status,
        description,
        actual_value,
        is_estimate_visit,
        estimate_job_id,
        account_id,
        created_at,
        updated_at,
        customer:customers!customer_id(name, email, phone)
      `
      )
      .eq("client_share_token", token)
      .maybeSingle();

    if (jobError || !job) {
      return jsonResponse({ error: "Job not found or link is invalid" }, 404);
    }

    if (req.method === "POST") {
      return await handleSingleJobPost(supabase, job, req);
    }

    if (req.method !== "GET") {
      return jsonResponse({ error: "Method not allowed" }, 405);
    }

    return await handleSingleJobGet(supabase, supabaseUrl, job, jsonResponse);
  } catch (error) {
    console.error("job-client-portal error:", error);
    return jsonResponse({ error: "Internal server error" }, 500);
  }
});

async function handleClientPortal(supabase: any, supabaseUrl: string, customer: any, jobId: string | null, req: Request) {
  if (req.method === "POST") {
    if (!jobId) {
      return jsonResponse({ error: "Job ID required for this action" }, 400);
    }
    const { data: job } = await supabase
      .from("leads")
      .select("id, customer_id, account_id")
      .eq("id", jobId)
      .eq("customer_id", customer.id)
      .maybeSingle();

    if (!job) {
      return jsonResponse({ error: "Job not found or access denied" }, 404);
    }

    return await handleSingleJobPost(supabase, { ...job, customer }, req);
  }

  if (req.method !== "GET") {
    return jsonResponse({ error: "Method not allowed" }, 405);
  }

  if (!jobId) {
    const { data: jobs } = await supabase
      .from("leads")
      .select(`
        id,
        name,
        address,
        service_type,
        status,
        created_at,
        updated_at,
        is_estimate_visit,
        estimate_job_id
      `)
      .eq("customer_id", customer.id)
      .neq("status", "archived")
      .order("created_at", { ascending: false });

    const { data: recurringJobs } = await supabase
      .from("recurring_jobs")
      .select(`
        id,
        name,
        address,
        service_type,
        frequency,
        start_date,
        end_date,
        created_at
      `)
      .eq("customer_id", customer.id)
      .order("created_at", { ascending: false });

    const { data: account } = await supabase
      .from("accounts")
      .select("company_name, company_email, company_phone, logo_url, settings")
      .eq("id", customer.account_id)
      .maybeSingle();

    const { data: invoices } = await supabase
      .from("invoices")
      .select(`
        id,
        lead_id,
        stripe_invoice_url,
        status,
        total,
        created_at,
        leads!inner(customer_id, name, service_type)
      `)
      .eq("leads.customer_id", customer.id)
      .order("created_at", { ascending: false });

    const regularJobs = (jobs || []).filter((j: any) => !j.is_estimate_visit);
    const estimateVisitJobs = (jobs || []).filter((j: any) => j.is_estimate_visit && !j.estimate_job_id);

    const displayJobs = regularJobs.length > 0 ? regularJobs : estimateVisitJobs;

    return jsonResponse({
      customer: {
        name: customer.name,
        email: customer.email,
        phone: customer.phone,
      },
      company: account
        ? {
            company_name: account.company_name,
            company_email: account.company_email,
            company_phone: account.company_phone,
            logo_url: account.logo_url,
            portal_color: account.settings?.client_portal_color ?? null,
            portal_text_color: account.settings?.client_portal_text_color ?? null,
            client_portal_color: account.settings?.client_portal_color ?? null,
            client_portal_text_color: account.settings?.client_portal_text_color ?? null,
            settings: account.settings ?? null,
          }
        : {},
      jobs: displayJobs.map((j: any) => ({
        id: j.id,
        name: j.name,
        address: j.address,
        service_type: j.service_type,
        status: j.status,
        created_at: j.created_at,
      })),
      recurring_jobs: (recurringJobs || []).map((rj: any) => ({
        id: rj.id,
        name: rj.name,
        address: rj.address,
        service_type: rj.service_type,
        frequency: rj.frequency,
        start_date: rj.start_date,
        end_date: rj.end_date,
        created_at: rj.created_at,
      })),
      invoices: (invoices || []).map((inv: any) => ({
        id: inv.id,
        lead_id: inv.lead_id,
        job_name: inv.leads?.name,
        service_type: inv.leads?.service_type,
        stripe_invoice_url: inv.stripe_invoice_url,
        status: inv.status,
        total: inv.total,
        created_at: inv.created_at,
      })),
    });
  }

  const { data: job } = await supabase
    .from("leads")
    .select(`
      id,
      name,
      address,
      service_type,
      status,
      description,
      actual_value,
      is_estimate_visit,
      estimate_job_id,
      account_id,
      created_at,
      updated_at
    `)
    .eq("id", jobId)
    .eq("customer_id", customer.id)
    .maybeSingle();

  if (job) {
    job.customer = customer;
    const jobDetails = await handleSingleJobGet(supabase, supabaseUrl, job, jsonResponse);
    const jobData = await jobDetails.json();
    return jsonResponse({
      ...jobData,
      portal_metadata: {
        customer: {
          name: customer.name,
          email: customer.email,
          phone: customer.phone,
        },
        has_portal: true,
      }
    });
  }

  const { data: recurringJob } = await supabase
    .from("recurring_jobs")
    .select("id, name, address, service_type, description, account_id, customer_id, frequency, start_date, end_date")
    .eq("id", jobId)
    .eq("customer_id", customer.id)
    .maybeSingle();

  if (recurringJob) {
    recurringJob.customer = customer;
    recurringJob.client_share_token = null;
    const jobDetails = await handleRecurringJobPortal(supabase, supabaseUrl, recurringJob, req, jsonResponse);
    const jobData = await jobDetails.json();
    return jsonResponse({
      ...jobData,
      portal_metadata: {
        customer: {
          name: customer.name,
          email: customer.email,
          phone: customer.phone,
        },
        has_portal: true,
      }
    });
  }

  return jsonResponse({ error: "Job not found or access denied" }, 404);
}

async function handleSingleJobPost(supabase: any, job: any, req: Request) {
  const body = await req.json();
  const action = body.action;
  const clientUpdatedAt = body.updated_at;
  const estimateVersionId = typeof body.estimate_version_id === "string" ? body.estimate_version_id : null;
  const signatureDataUrl =
    typeof body.signature_data_url === "string"
      ? body.signature_data_url
      : typeof body.signatureDataUrl === "string"
        ? body.signatureDataUrl
        : null;
  const agreementAcceptance =
    body && typeof body.agreement_acceptance === "object" && body.agreement_acceptance
      ? body.agreement_acceptance
      : null;
  const agreementTemplates =
    body && typeof body.agreement_templates === "object" && body.agreement_templates
      ? body.agreement_templates
      : null;
  let requiredDocumentConfigIds: string[] = [];

  if (action === "approve") {
    const baseDocumentLeadIds = [
      typeof job?.estimate_job_id === "string" ? job.estimate_job_id : null,
      typeof job?.id === "string" ? job.id : null,
    ].filter((value): value is string => Boolean(value));
    const portalDocuments = await fetchPortalDocumentsForLeadFamily(
      supabase,
      Deno.env.get("SUPABASE_URL")!,
      baseDocumentLeadIds,
      "approval required documents",
    );
    requiredDocumentConfigIds = (portalDocuments.configs || [])
      .filter((config: any) => {
        const timing = String(config?.email_timing || "").trim().toLowerCase().replace(/[\s-]+/g, "_");
        return config?.include_in_job === true
          && timing === "on_estimate_approval"
          && config?.requires_signature === true;
      })
      .map((config: any) => String(config.id || ""))
      .filter(Boolean);
  }

  if (action === "sign_job_release") {
    return await signJobRelease(
      supabase,
      { id: job.id, account_id: job.account_id, customer_id: job.customer_id },
      signatureDataUrl,
      jsonResponse,
    );
  }

  if (action !== "approve" && action !== "decline" && action !== "approve_changes" && action !== "decline_changes") {
    return jsonResponse({ error: "Invalid action" }, 400);
  }

  const { data: estimate, error: estError } = await supabase
    .from("estimates")
    .select("id, status, expires_at, job_id, updated_at, has_pending_changes, account_id, proposal_settings")
    .eq("job_id", job.id)
    .maybeSingle();

  if (estError || !estimate) {
    const { data: parentLead } = await supabase
      .from("leads")
      .select("id")
      .eq("estimate_job_id", job.id)
      .maybeSingle();

    if (!parentLead) {
      return jsonResponse({ error: "No estimate found for this job" }, 404);
    }

    const { data: parentEstimate, error: peError } = await supabase
      .from("estimates")
      .select("id, status, expires_at, job_id, updated_at, has_pending_changes, account_id, proposal_settings")
      .eq("job_id", parentLead.id)
      .maybeSingle();

    if (peError || !parentEstimate) {
      return jsonResponse({ error: "No estimate found for this job" }, 404);
    }

    return await handleEstimateAction(
      supabase,
      parentEstimate,
      action,
      job.id,
      jsonResponse,
      clientUpdatedAt,
      estimateVersionId,
      signatureDataUrl,
      agreementAcceptance,
      agreementTemplates,
      requiredDocumentConfigIds,
    );
  }

  return await handleEstimateAction(
    supabase,
    estimate,
    action,
    job.id,
    jsonResponse,
    clientUpdatedAt,
    estimateVersionId,
    signatureDataUrl,
    agreementAcceptance,
    agreementTemplates,
    requiredDocumentConfigIds,
  );
}

import { uploadJobReleaseSignatureDataUrl } from "./signature.ts";

export async function isLeadFullyPaid(supabase: any, leadId: string): Promise<boolean> {
  const { data: invoices } = await supabase
    .from("invoices")
    .select("id, status, balance_due")
    .eq("lead_id", leadId);

  const rows = invoices || [];
  if (rows.length === 0) return false;

  return rows.every((invoice: any) => invoice.status === "paid" && Number(invoice.balance_due || 0) <= 0);
}

export async function getJobReleaseForLead(supabase: any, leadId: string) {
  const { data } = await supabase
    .from("job_releases")
    .select("id, status, release_text, signed_at, signature_image_url, requested_at")
    .eq("lead_id", leadId)
    .maybeSingle();

  return data || null;
}

export async function signJobRelease(
  supabase: any,
  lead: { id: string; account_id: string; customer_id: string },
  signatureDataUrl: string | null,
  jsonResponse: (body: unknown, status?: number) => Response,
) {
  const fullyPaid = await isLeadFullyPaid(supabase, lead.id);
  if (!fullyPaid) {
    return jsonResponse({ error: "Job release can only be signed after all invoices are fully paid." }, 400);
  }

  const { data: jobRelease, error: releaseError } = await supabase
    .from("job_releases")
    .select("id, status")
    .eq("lead_id", lead.id)
    .maybeSingle();

  if (releaseError || !jobRelease) {
    return jsonResponse({ error: "Job release not found for this job." }, 404);
  }

  if (jobRelease.status === "signed") {
    return jsonResponse({ error: "Job release has already been signed." }, 400);
  }

  let signaturePublicUrl: string | null = null;
  if (signatureDataUrl) {
    const uploadResult = await uploadJobReleaseSignatureDataUrl(supabase, jobRelease.id, signatureDataUrl);
    if (!uploadResult.ok) {
      return jsonResponse({ error: uploadResult.error }, uploadResult.statusCode);
    }
    signaturePublicUrl = uploadResult.publicUrl;
  }

  const { error: updateError } = await supabase
    .from("job_releases")
    .update({
      status: "signed",
      signed_at: new Date().toISOString(),
      signature_image_url: signaturePublicUrl,
      updated_at: new Date().toISOString(),
    })
    .eq("id", jobRelease.id)
    .eq("status", "pending_signature");

  if (updateError) {
    return jsonResponse({ error: "Failed to sign job release." }, 500);
  }

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const anonKey = Deno.env.get("SUPABASE_ANON_KEY") || "";
    await fetch(`${supabaseUrl}/functions/v1/send-job-release-notifications`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...(anonKey ? { Authorization: `Bearer ${anonKey}`, apikey: anonKey } : {}),
      },
      body: JSON.stringify({ job_release_id: jobRelease.id, event_type: "signed_copy" }),
    });
  } catch (error) {
    console.error("Failed to dispatch signed job release notifications:", error);
  }

  return jsonResponse({ success: true, message: "Job release signed." });
}

export type PortalJobDocumentConfig = {
  id: string;
  lead_id: string;
  template_id: string;
  include_in_job: boolean;
  email_timing: string;
  requires_signature: boolean;
  sort_order: number;
  template: {
    id: string;
    name: string;
    system_key: string | null;
    body: string | null;
  } | null;
};

export type PortalJobDocument = {
  id: string;
  lead_id: string;
  template_id: string | null;
  config_id: string | null;
  document_key: string;
  file_name: string;
  file_path: string;
  mime_type: string | null;
  created_at: string;
  url: string;
};

async function expandLeadFamilyIds(supabase: any, seedLeadIds: string[], errorContext: string) {
  const relatedLeadFamilyIds = new Set<string>(seedLeadIds.filter(Boolean));

  if (seedLeadIds.length === 0) {
    return Array.from(relatedLeadFamilyIds);
  }

  const [relatedByIdResult, relatedByEstimateJobIdResult] = await Promise.all([
    supabase
      .from("leads")
      .select("id, estimate_job_id")
      .in("id", seedLeadIds),
    supabase
      .from("leads")
      .select("id, estimate_job_id")
      .in("estimate_job_id", seedLeadIds),
  ]);

  if (relatedByIdResult.error) {
    console.error(`Failed to fetch ${errorContext} related leads by id:`, relatedByIdResult.error);
  }
  if (relatedByEstimateJobIdResult.error) {
    console.error(
      `Failed to fetch ${errorContext} related leads by estimate_job_id:`,
      relatedByEstimateJobIdResult.error,
    );
  }

  const relatedLeadRows = [
    ...(relatedByIdResult.data || []),
    ...(relatedByEstimateJobIdResult.data || []),
  ];

  for (const row of relatedLeadRows) {
    const id = String((row as any)?.id || "");
    const estimateJobId = String((row as any)?.estimate_job_id || "");
    if (id) relatedLeadFamilyIds.add(id);
    if (estimateJobId) relatedLeadFamilyIds.add(estimateJobId);
  }

  return Array.from(relatedLeadFamilyIds);
}

export async function fetchPortalDocumentsForLeadFamily(
  supabase: any,
  supabaseUrl: string,
  seedLeadIds: string[],
  errorContext = "portal documents",
): Promise<{
  leadIds: string[];
  leadId: string | null;
  configs: PortalJobDocumentConfig[];
  documents: PortalJobDocument[];
}> {
  const leadIds = await expandLeadFamilyIds(supabase, seedLeadIds, errorContext);

  if (leadIds.length === 0) {
    return {
      leadIds,
      leadId: null,
      configs: [],
      documents: [],
    };
  }

  const readConfigs = async () =>
    supabase
      .from("job_document_configs")
      .select(
        "id, lead_id, template_id, include_in_job, email_timing, requires_signature, sort_order, template:document_templates(id, name, system_key, body)",
      )
      .in("lead_id", leadIds)
      .order("sort_order", { ascending: true });

  let { data: configRows, error: configError } = await readConfigs();

  if (!configError && (configRows || []).length === 0) {
    const defaultLeadId = seedLeadIds.find(Boolean) || leadIds[0] || null;
    if (defaultLeadId) {
      const { data: leadRow, error: leadError } = await supabase
        .from("leads")
        .select("id, account_id")
        .eq("id", defaultLeadId)
        .maybeSingle();

      if (leadError) {
        console.error(`Failed to fetch ${errorContext} lead for default config seed:`, leadError);
      } else {
        const accountId = String(leadRow?.account_id || "");
        if (accountId) {
          const { data: templateRows, error: templateError } = await supabase
            .from("document_templates")
            .select("id, default_email_timing, default_requires_signature")
            .eq("account_id", accountId)
            .eq("default_included_in_jobs", true)
            .order("created_at", { ascending: true });

          if (templateError) {
            console.error(`Failed to fetch ${errorContext} default templates for config seed:`, templateError);
          }
          else {
            const templates = (templateRows || []).filter((row: any) => String(row?.id || ""));
            if (templates.length > 0) {
              const insertPayload = templates.map((template: any, index: number) => ({
                lead_id: defaultLeadId,
                account_id: accountId,
                template_id: String(template.id),
                include_in_job: true,
                email_timing: String(template.default_email_timing || "never"),
                requires_signature: template.default_requires_signature === true,
                sort_order: index,
                created_by: null,
              }));

              const { error: seedError } = await supabase
                .from("job_document_configs")
                .insert(insertPayload);

              if (seedError) {
                console.error(`Failed to seed ${errorContext} default configs:`, seedError);
              } else {
                const refreshed = await readConfigs();
                configRows = refreshed.data;
                configError = refreshed.error;
              }
            }
          }
        }
      }
    }
  }

  let configs: PortalJobDocumentConfig[] = [];
  if (configError) {
    console.error(`Failed to fetch ${errorContext} configs:`, configError);
  } else {
    const normalizedConfigRows = (configRows || [])
      .map((rawRow: any) => {
        const templateRaw = rawRow?.template;
        const template = Array.isArray(templateRaw) ? templateRaw[0] : templateRaw;
        return {
          id: String(rawRow?.id || ""),
          lead_id: String(rawRow?.lead_id || ""),
          template_id: String(rawRow?.template_id || ""),
          include_in_job: rawRow?.include_in_job === true,
          email_timing: String(rawRow?.email_timing || "never"),
          requires_signature: rawRow?.requires_signature === true,
          sort_order: Number(rawRow?.sort_order || 0),
          template: template
            ? {
                id: String(template.id || ""),
                name: String(template.name || ""),
                system_key: template.system_key ? String(template.system_key) : null,
                body: typeof template.body === "string" ? template.body : null,
              }
            : null,
        };
      })
      .filter((row) => Boolean(row.id) && Boolean(row.lead_id));

    const leadPriority = new Map(leadIds.map((id, index) => [id, index]));
    configs = normalizedConfigRows.sort((a, b) => {
      const aPriority = leadPriority.get(a.lead_id) ?? Number.MAX_SAFE_INTEGER;
      const bPriority = leadPriority.get(b.lead_id) ?? Number.MAX_SAFE_INTEGER;
      if (aPriority !== bPriority) return aPriority - bPriority;
      return a.sort_order - b.sort_order;
    });
  }

  const { data: documentRows, error: documentsError } = await supabase
    .from("job_documents")
    .select("id, lead_id, template_id, config_id, document_key, file_name, file_path, mime_type, created_at")
    .in("lead_id", leadIds)
    .order("created_at", { ascending: false });

  let documents: PortalJobDocument[] = [];
  if (documentsError) {
    console.error(`Failed to fetch ${errorContext} records:`, documentsError);
  } else {
    const selectedConfigIds = new Set(configs.map((config) => config.id));
    const selectedTemplateIds = new Set(configs.map((config) => config.template_id).filter(Boolean));

    documents = (documentRows || [])
      .map((rawDocument: any) => ({
        id: String(rawDocument?.id || ""),
        lead_id: String(rawDocument?.lead_id || ""),
        template_id: rawDocument?.template_id ? String(rawDocument.template_id) : null,
        config_id: rawDocument?.config_id ? String(rawDocument.config_id) : null,
        document_key: String(rawDocument?.document_key || ""),
        file_name: String(rawDocument?.file_name || ""),
        file_path: String(rawDocument?.file_path || ""),
        mime_type: rawDocument?.mime_type ? String(rawDocument.mime_type) : null,
        created_at: String(rawDocument?.created_at || ""),
        url: `${supabaseUrl}/storage/v1/object/public/job-documents/${rawDocument.file_path}`,
      }))
      .filter((document) => {
        if (!document.id || !document.file_path) return false;
        if (document.config_id && selectedConfigIds.has(document.config_id)) return true;
        if (selectedConfigIds.size === 0) return true;
        if (document.template_id && selectedTemplateIds.has(document.template_id)) return true;
        return leadIds.includes(document.lead_id);
      });
  }

  return {
    leadIds,
    leadId: leadIds[0] || null,
    configs,
    documents,
  };
}

const MAX_SIGNATURE_IMAGE_BYTES = 6 * 1024 * 1024;

export function isManualApprovalPhotoUrlColumnMissing(error: unknown): boolean {
  if (!error || typeof error !== "object") return false;
  const code = (error as { code?: string }).code;
  if (code === "42703") return true;

  const message = [
    (error as { message?: string }).message,
    (error as { details?: string }).details,
    (error as { hint?: string }).hint,
  ]
    .filter((part): part is string => typeof part === "string")
    .join(" ")
    .toLowerCase();

  return message.includes("manual_approval_photo_url");
}

function decodeBase64(base64: string): Uint8Array {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }
  return bytes;
}

function parseSignatureDataUrl(signatureDataUrl: string): { bytes: Uint8Array; contentType: string; extension: string } | null {
  const trimmedValue = signatureDataUrl.trim();
  const match = trimmedValue.match(/^data:(image\/(?:png|jpeg|jpg|webp));base64,([A-Za-z0-9+/=]+)$/i);
  if (!match) return null;

  const contentType = match[1].toLowerCase() === "image/jpg" ? "image/jpeg" : match[1].toLowerCase();
  const extensionByContentType: Record<string, string> = {
    "image/png": "png",
    "image/jpeg": "jpg",
    "image/webp": "webp",
  };
  const extension = extensionByContentType[contentType];
  if (!extension) return null;

  let bytes: Uint8Array;
  try {
    bytes = decodeBase64(match[2]);
  } catch {
    return null;
  }

  if (!bytes.length || bytes.length > MAX_SIGNATURE_IMAGE_BYTES) {
    return null;
  }

  return { bytes, contentType, extension };
}

export async function uploadSignatureDataUrl(
  supabase: any,
  estimateId: string,
  signatureDataUrl: string,
): Promise<{ ok: true; filePath: string; publicUrl: string } | { ok: false; error: string; statusCode: number }> {
  const parsedImage = parseSignatureDataUrl(signatureDataUrl);
  if (!parsedImage) {
    return { ok: false, error: "Invalid signature format. Please sign again.", statusCode: 400 };
  }

  const filePath = `estimate-approvals/${estimateId}/${crypto.randomUUID()}.${parsedImage.extension}`;
  const { error: uploadError } = await supabase.storage
    .from("lead-photos")
    .upload(filePath, parsedImage.bytes, {
      contentType: parsedImage.contentType,
      upsert: false,
    });

  if (uploadError) {
    return { ok: false, error: "Failed to upload signature image", statusCode: 500 };
  }

  const { data: urlData } = supabase.storage.from("lead-photos").getPublicUrl(filePath);
  return { ok: true, filePath, publicUrl: urlData.publicUrl };
}

export async function uploadJobReleaseSignatureDataUrl(
  supabase: any,
